class OpenCLNumeric(CNumeric):
    """OpenCL-side numeric wrapper."""


class OpenCLLibRoutineVariable(LibRoutineVariable):
    """Shared OpenCL variable behaviour."""

    DTYPE_LOOKUP = {
        "f64": "double",
        "f32": "float",
        "i64": "long",
        "i32": "int",
    }

    def lookup_dtype(self, dtype):
        """Translate an internal dtype token to an OpenCL C type name."""
        if dtype in type(self).DTYPE_LOOKUP:
            return type(self).DTYPE_LOOKUP[dtype]
        raise ValueError(f"Unknown dtype: {dtype}")

    def expr_at(self, offset_string):
        """Render indexed array access."""
        return f"{self.name}[{offset_string}]"

    def get_zero_value(self):
        if self.dtype == "f32":
            return "0.0f"
        if self.dtype.startswith("f") or self.dtype.startswith("c"):
            return "0.0"
        return "0"

    def get_definition_lines(self):
        """Emit local storage declarations."""
        dtype = self.lookup_dtype(self._dtype)
        if self.is_scalar:
            yield f"{dtype} {self._name};"
            return
        yield f"{dtype} {self._name}[{self._size}];"


class OpenCLLocalVariable(OpenCLLibRoutineVariable, LibRoutineLocalVariable):
    """Local OpenCL variable."""


class OpenCLDummyVariable(OpenCLLibRoutineVariable):
    """Base class for OpenCL routine arguments."""

    _intent = None

    def _intent_is_const(self):
        return type(self)._intent == "RO"

    def _intent_is_pointer(self):
        return type(self)._intent in {"WO", "RW"}

    def get_definition_lines(self):
        """Arguments are declared in the signature, not in the body."""
        yield self.as_argument_declaration()

    def as_argument_declaration(self):
        """Render the OpenCL kernel or helper argument declaration."""
        dtype = self.lookup_dtype(self._dtype)
        const = "const " if self._intent_is_const() else ""
        if self.is_scalar:
            if self._intent_is_pointer():
                return f"__global {dtype} *{self._name}"
            return f"{const}{dtype} {self._name}"
        return f"{const}__global {dtype} *{self._name}"

    def expr(self):
        """Dereference scalar output pointers transparently."""
        if self.is_scalar and self._intent_is_pointer():
            return f"(*{self.name})"
        return super().expr()


class OpenCLInputVariable(OpenCLDummyVariable, LibRoutineInputVariable):
    """Read-only OpenCL argument."""

    _intent = "RO"


class OpenCLOutputVariable(OpenCLDummyVariable, LibRoutineOutputVariable):
    """Write-only OpenCL argument."""

    _intent = "WO"


class OpenCLInOutVariable(OpenCLDummyVariable, LibRoutineInOutVariable):
    """Read-write OpenCL argument."""

    _intent = "RW"


class OpenCLBufferVariable(OpenCLInOutVariable, LibRoutineBufferVariable):
    """Buffer-backed OpenCL argument."""

    _intent = "RW"


class OpenCLConstant(OpenCLLibRoutineVariable, LibRoutineConstant):
    """Program-scope OpenCL constant definition."""

    def get_definition_lines(self):
        """Emit OpenCL ``__constant`` definitions."""
        dtype = self.lookup_dtype(self._dtype)
        if self.is_scalar:
            yield f"__constant {dtype} {self._name} = {self.value};"
            return

        prefix = f"__constant {dtype} {self._name}[{self.size}] = {{"
        values = [
            int(v) if self.dtype[0] == "i" else float(v) for v in self.values
        ]
        for line in multiline_iterable(
            values,
            separator=", ",
            max_line_length=100,
            indent="",
            extra_indent="    ",
            linebreak="",
            prefix=prefix,
            suffix="};",
            prefix_suffix_lines=False,
        ):
            yield line


class OpenCLAssignmentStatementLine(CAssignmentStatementLine):
    """OpenCL assignment statement."""


class OpenCLRoutineCallContainer(CRoutineCallContainer):
    """Routine call inside OpenCL C source."""

    def get_call_string(self):
        """Render a plain device-function call."""
        imported = self._imp_routine.imported
        if imported.is_kernel:
            raise ValueError(
                "OpenCL kernels cannot be called from generated OpenCL source. "
                "Use a helper routine without kernel resources or wrap the "
                "kernel directly from Python."
            )
        return f"{self.get_call_name()}({', '.join(self.get_args_list())});"


class OpenCLCommentLine(CCommentLine):
    """OpenCL uses C-style line comments."""


class OpenCLLoopMultiFrameExpandContainer(MultiFrameExpandContainer):
    """OpenCL fallback loop expansion for non-kernel resources."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = OpenCLLocalVariable

    def generate_head_containers(self):
        """Emit the ``for`` loop header."""
        if self._multiframe_variable is not None:
            expr = self._multiframe_variable.expr()
            yield from self.codelines_from_text(
                f"for ({expr} = {self._min_value}; {expr} < {self._max_value}; ++{expr}) {{"
            )

    def generate_foot_containers(self):
        """Close the fallback loop block."""
        if self._multiframe_variable is not None:
            yield from self.codelines_from_text("}")


class OpenCLMultiFrameExpandContainer(MultiFrameExpandContainer):
    """Map a multiframe selector to an OpenCL kernel request."""

    INDENT_BODY = False
    DEFAULT_LOCAL_VARIABLE_CLASS = OpenCLLocalVariable

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._request = None

    def generate_head_containers(self):
        """Assign the selector from the request expression."""
        if self._multiframe_variable is not None and self._request is not None:
            yield from self.codelines_from_text(
                f"{self._multiframe_variable.local} = {self._request.expr()};"
            )

    def generate_foot_containers(self):
        """Kernel selector assignment does not need a foot section."""
        return iter([])

    def assign_request_parameters(
        self, request, local_variable_class=None, local_variable_capture=None
    ):
        """Store the request and make it visible to the local capture layer."""
        if local_variable_class is None:
            local_variable_class = type(self).DEFAULT_LOCAL_VARIABLE_CLASS
        self._request = request
        if local_variable_capture is None:
            local_variable_capture = self._local_variable_capture
        if local_variable_capture is not None:
            local_variable_capture.requires(self._request)


class OpenCLIntCombineExpandContainer(CIntCombineExpandContainer):
    """Combine split selectors into one flattened OpenCL index."""

    INDENT_BODY = True
    DEFAULT_LOCAL_VARIABLE_CLASS = OpenCLLocalVariable


class OpenCLKernelRequest(KernelRequest):
    """Base class for OpenCL kernel launch metadata."""

    _id = ""
    opencl_function = None

    def __init__(self, num, axis):
        self._num = num
        self._axis = int(axis)
        super().__init__(
            descriptor=f"{type(self).__name__}_{self._axis}_{num}",
            max_value=num,
            min_value=0,
            source=None,
        )

    def expr(self):
        """Render the OpenCL builtin that provides this selector."""
        return f"{type(self).opencl_function}({self._axis})"

    @property
    def launch_extent(self):
        """Extent contributed by this launch request."""
        return self._num

    @property
    def launch_axis(self):
        """Axis index contributed by this launch request."""
        return self._axis

    @property
    def launch_role(self):
        """Role within the OpenCL launch configuration."""
        raise NotImplementedError("must be implemented in subclass")


class OpenCLKernelLocalRequest(OpenCLKernelRequest):
    """Local-work-size request based on ``get_local_id``."""

    _id = "L"
    opencl_function = "get_local_id"
    launch_role = "local"


class OpenCLKernelGroupRequest(OpenCLKernelRequest):
    """Group-count request based on ``get_group_id``."""

    _id = "G"
    opencl_function = "get_group_id"
    launch_role = "group"


class OpenCLHostResource(ComputeResource):
    """Fallback resource that expands multiframes as explicit loops."""

    DEFAULT_LOCAL_VARIABLE_CLASS = OpenCLLocalVariable

    def create_mfe_container(
        self,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ):
        """Create a plain loop-based multiframe container."""
        del name, loop_container, loop_capture
        return OpenCLLoopMultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def create_combine_container(
        self,
        first,
        second,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ):
        """Create the flattened-index combination container."""
        del name, loop_container, loop_capture
        return OpenCLIntCombineExpandContainer(
            first,
            second,
            context=context,
            local_variable_capture=local_variable_capture,
        )


class OpenCLDeviceResource(ComputeResource):
    """Kernel-capable OpenCL compute resource."""

    DEFAULT_LOCAL_VARIABLE_CLASS = OpenCLLocalVariable

    def __init__(
        self,
        descriptor="DEFAULT_OPENCL_DEVICE",
        local_axes=(0, 1, 2),
        nlocals=256,
        group_axes=(0, 1, 2),
        ngroups=(1 << 32),
        outer_layer=None,
        next_layer=None,
        max_value=None,
    ):
        if max_value is None:
            max_value = nlocals
        super().__init__(
            descriptor,
            outer_layer=outer_layer,
            next_layer=next_layer,
            max_value=max_value,
        )
        self._avail_local_dim = nlocals
        self._avail_group_dim = ngroups
        self._avail_local_axes = tuple(local_axes)
        self._avail_group_axes = tuple(group_axes)
        if next_layer is not None:
            self._next_layer = next_layer

    def get_default_resource(self):
        """Once device resources are exhausted, fall back to plain loops."""
        return OpenCLHostResource("DEFAULT", outer_layer=self)

    def create_combine_container(
        self,
        first,
        second,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ):
        """Create the flattened-index combination container."""
        del name, loop_container, loop_capture
        return OpenCLIntCombineExpandContainer(
            first,
            second,
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def request_mfe_container(
        self,
        variable,
        *,
        name=None,
        local_variable_capture=None,
        loop_capture=None,
        context,
    ):
        """
        Request a multiframe expansion container from this resource.

        Large ranges are split recursively and combined afterwards. Small enough
        ranges are mapped to local or group kernel requests.
        """
        if variable.max_value > self._max_value:
            first, second = variable.split(self._max_value)

            if loop_capture is None:
                return None

            loop_capture.requires(second)
            loop_capture.requires(first)

            mfe_container = self.create_combine_container(
                first,
                second,
                context=context,
                local_variable_capture=local_variable_capture,
            )
            reduced = self
        else:
            request, reduced = self.exhaust(variable)
            if reduced is None:
                return super().request_mfe_container(
                    variable,
                    name=name,
                    local_variable_capture=local_variable_capture,
                    loop_capture=loop_capture,
                    context=context,
                )

            mfe_container = self.create_mfe_container(
                context=context,
                local_variable_capture=local_variable_capture,
                loop_capture=loop_capture,
            )
            mfe_container.assign_request_parameters(
                request,
                local_variable_capture=local_variable_capture,
                local_variable_class=type(self).DEFAULT_LOCAL_VARIABLE_CLASS,
            )

        if mfe_container is None:
            return self, None

        mfe_container.assign_multiframe_variable(
            variable,
            name=name,
            local_variable_class=type(self).DEFAULT_LOCAL_VARIABLE_CLASS,
        )
        return reduced, mfe_container

    def exhaust(self, variable):
        """Consume one local or group axis for a kernel selector."""
        num = variable.max_value

        if len(self._avail_local_axes) > 0 and num <= self._avail_local_dim:
            axis, *remaining_axes = self._avail_local_axes
            remaining_dim = max(1, self._avail_local_dim // num)
            max_value = max(remaining_dim, self._avail_group_dim)
            reduced = OpenCLDeviceResource(
                self._descriptor + f"-L{axis}{num}",
                local_axes=tuple(remaining_axes),
                nlocals=remaining_dim,
                group_axes=self._avail_group_axes,
                ngroups=self._avail_group_dim,
                outer_layer=None,
                next_layer=self._next_layer,
                max_value=max_value,
            )
            return OpenCLKernelLocalRequest(num, axis), reduced

        if len(self._avail_group_axes) > 0 and num <= self._avail_group_dim:
            axis, *remaining_axes = self._avail_group_axes
            remaining_dim = max(1, self._avail_group_dim // num)
            reduced = OpenCLDeviceResource(
                self._descriptor + f"-G{axis}{num}",
                local_axes=(),
                nlocals=1,
                group_axes=tuple(remaining_axes),
                ngroups=remaining_dim,
                outer_layer=None,
                next_layer=self._next_layer,
                max_value=remaining_dim,
            )
            return OpenCLKernelGroupRequest(num, axis), reduced

        return None, None

    def create_mfe_container(
        self,
        *,
        name=None,
        local_variable_capture=None,
        loop_container=None,
        loop_capture=None,
        context,
    ):
        """Create a kernel-selector container."""
        del name, loop_container, loop_capture
        return OpenCLMultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
        )


class OpenCLRoutineContainer(CRoutineContainer):
    """OpenCL routine container with optional kernel qualifier."""

    INPUT_VARIABLE_CLASS = OpenCLInputVariable
    KERNEL_REQUEST_CLASS = OpenCLKernelRequest

    def __init__(self, *args, **kwargs):
        self._ker_layer = None
        super().__init__(*args, **kwargs)

    def prepare_hidden_layers(self, **buildargs):
        """Create the standard hidden layers and the kernel-request layer."""
        self._context_main_ptr = super().prepare_hidden_layers(**buildargs)
        self._ker_layer = self.add_hidden_layer(CaptureContainer, **buildargs)
        return self._context_main_ptr

    def configure_container(self, **buildargs):
        """Capture kernel requests separately from ordinary arguments."""
        self._ker_layer.add_capture_trigger(KernelRequest)
        return super().configure_container(**buildargs)

    @property
    def is_kernel(self):
        """Whether this routine became an OpenCL kernel."""
        return isinstance(self.context.resource, OpenCLDeviceResource) or any(
            True for _ in self.get_kernel_variables()
        )

    def get_kernel_variables(self, **_):
        """Yield the kernel launch requests captured for this routine."""
        for variable in self._ker_layer.captured:
            if isinstance(variable, KernelRequest):
                yield variable

    def get_argument_variables(self, **_):
        """Yield ordinary routine arguments while hiding kernel requests."""
        for variable in sorted(self._arg_layer.captured):
            if isinstance(variable, type(self).KERNEL_REQUEST_CLASS):
                continue
            yield variable

    def prepare_call_arguments(self):
        """Prepare the call argument list after capture completed."""
        self._call_args = []
        num = 0
        for variable in self._arg_layer.captured:
            if isinstance(variable, KernelRequest):
                continue
            if isinstance(variable, LibRoutineMultiFrame):
                name = f"krnl_{num:02d}"
                num += 1
                loc = variable.create_input_representative(
                    context=self.context,
                    dtype="i32",
                    size=None,
                    name=name,
                    input_variable_class=type(self).INPUT_VARIABLE_CLASS,
                    autorequire=False,
                )
                self._ios_layer.requires(loc)
            else:
                self._ios_layer.requires(variable)
            self._call_args.append(variable)

    def get_signature(self, *, terminate=False):
        """Render the OpenCL kernel or helper signature."""
        call_args = list(
            variable.as_argument_declaration()
            for variable in self.get_argument_variables()
        )
        args_string = ", ".join(call_args) if call_args else "void"
        signature = f"void {self.name}({args_string})"
        if self.is_kernel:
            signature = f"__kernel {signature}"
        if terminate:
            signature += ";"
        return signature


class OpenCLImportContainer(ImportContainer):
    """OpenCL import placeholder rendered as a source include."""

    def __init__(self, library, routines, *, context, **kwargs):
        super().__init__(library, routines, context=context, **kwargs)
        self.library = library
        self.routines = tuple(routines)

    def construct_code_lines(self, **_):
        """Emit the OpenCL include for a dependency source file."""
        yield f'#include "{self.library.libname}.cl"'


class OpenCLImportSectionContainer(CImportSectionContainer):
    """Import handling using helper-function names inside OpenCL C."""

    def compose_call_name(self, importable, library):
        """Use the imported routine name directly."""
        del library
        return importable.name


class OpenCLBuilder(CBuilder, identifier="OPENCL"):
    """OpenCL builder using the C lowering with kernel-aware selectors."""

    _assignment_class = OpenCLAssignmentStatementLine

    def create_libroutine_variable(
        self,
        *,
        name,
        dtype,
        status,
        size,
        assignment=None,
        namespace=None,
        **kwargs,
    ):
        """Create the backend-specific routine variable implementation."""
        if status & LibRoutineVariable.STATUS_BUFFER:
            return OpenCLBufferVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        status = status & 3
        if status == LibRoutineVariable.STATUS_INPUT:
            return OpenCLInputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_OUTPUT:
            return OpenCLOutputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_INOUT:
            return OpenCLInOutVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        return super().create_libroutine_variable(
            name=name,
            dtype=dtype,
            status=status,
            size=size,
            assignment=assignment,
            namespace=namespace,
            **kwargs,
        )

    def as_numeric(self, variable):
        """Wrap a plain numeric literal for OpenCL source rendering."""
        return OpenCLNumeric(variable)

    def create_external_array(self, *args, context, **kwargs):
        """Create an external constant array for OpenCL source."""
        return Builder.create_external_array(
            self,
            *args,
            context=context,
            local_class=OpenCLLocalVariable,
            constant_class=OpenCLConstant,
        )


class OpenCLLibRoutine(LibRoutine):
    """OpenCL library routine descriptor."""

    def __init__(self, *args, is_kernel=False, **kwargs):
        super().__init__(*args, **kwargs)
        self._explicit_is_kernel = bool(is_kernel)

    @property
    def is_kernel(self):
        container = self.container
        return bool(
            self._explicit_is_kernel
            or (container is not None and getattr(container, "is_kernel", False))
        )


class OpenCLLibrary(Library):
    """OpenCL source emission."""

    BACKEND_IDENTIFIER = "opencl"
    FILEENDING = "cl"
    INDENTSTR = "    "
    LIBROUTINE_CLASS = OpenCLLibRoutine
    IMPORTLINE_CLASS = OpenCLImportContainer
    DEFAULT_BUILDER = OpenCLBuilder
    DEFAULT_CONTAINER_CLASS = OpenCLRoutineContainer

    def __init__(
        self,
        plain_name,
        build_hash=None,
        resource=None,
        configuration=None,
        general_configuration=None,
    ):
        if resource is None:
            resource = OpenCLDeviceResource("OpenCLResource")
        self._initialize_library_state(
            plain_name=plain_name,
            build_hash=build_hash,
            resource=resource,
            import_section_class=OpenCLImportSectionContainer,
            backend_configuration=configuration,
            general_configuration=general_configuration,
        )

    def generate_head_containers(self, **_):
        """Emit the library preamble."""
        yield from self.codelines_from_text("// autogenerated opencl library")
        yield from self.codelines_from_text(
            "#pragma OPENCL EXTENSION cl_khr_fp64 : enable"
        )
        yield from self.codelines_from_text("")

    def generate_foot_containers(self, **_):
        """The OpenCL source does not need a closing library marker."""
        return
        yield

    def generate_prmb_containers(self, **_):
        """Emit includes and program-scope constants."""
        imports = list(self.import_capture.list_imports())
        if imports:
            for library, routines in imports:
                yield OpenCLImportContainer(
                    library, routines, context=self.context
                )
            yield from self.codelines_from_text("")

        constants = list(self.definition_capture.captured)
        if constants:
            for variable in constants:
                for line in variable.get_definition_lines():
                    yield from self.codelines_from_text(line)
            yield from self.codelines_from_text("")

    def generate_clsg_containers(self, **_):
        """The OpenCL source does not need a closing section."""
        return
        yield

    def get_to_zero_support_routine(self, dtype):
        """Return the external helper routine used to reset one buffer."""
        routine_name = f"phoenix_to_zero_{dtype}"
        existing = self[routine_name]
        if existing is not None:
            return existing
        zero_value = OpenCLLocalVariable(
            name="tmp", dtype=dtype, no_entry=True
        ).get_zero_value()
        ctype = OpenCLLocalVariable.DTYPE_LOOKUP[dtype]
        code = [
            f"inline void {routine_name}(__global {ctype} *buffer, int size)",
            "{",
            "    for (int idx = 0; idx < size; ++idx) {",
            f"        buffer[idx] = {zero_value};",
            "    }",
            "}",
        ]
        return self._register_manual_routine(
            routine_name,
            code=code,
            arguments=[
                {
                    "name": "buffer",
                    "dtype": dtype,
                    "size": 1,
                    "status": "INOUT",
                    "assignment": ("buffer", "data"),
                },
                {
                    "name": "size",
                    "dtype": "i32",
                    "status": "IN",
                },
            ],
        )

    def get_manifest_payload(self):
        payload = super().get_manifest_payload()
        for routine_entry, (_name, libroutine) in zip(
            payload["compatibility"]["routines"], self.content, strict=True
        ):
            routine_entry["kernel"] = bool(libroutine.is_kernel)
        return payload

    def get_codelines(self, indent=0):
        """Render the OpenCL library without the generic outer wrapper text."""
        yield from self.get_codelines_head(indent=indent)
        yield from self.get_codelines_prmb(indent=indent)
        yield from self.iter_routine_codelines(indent=indent)


